package com.anuj.obsidian.ui.visualizer

import java.io.File

/**
 * =========================================================================================
 * OBSIDIAN MILKDROP INTERMEDIATE REPRESENTATION (MilkPresetIR)
 * =========================================================================================
 * Decoupled from Android Compose UI rendering.
 * Generated by the .milk Parser, compiled into AST Programs, and executed by the GPU Renderer.
 * =========================================================================================
 */

data class MilkPresetMetadata(
    val id: Int,
    val name: String,
    val author: String = "Unknown",
    val description: String = "",
    val version: Float = 2.0f,
    val milkdropPresetVersion: Int = 200,
    val psVersion: Int = 2,
    val psVersionWarp: Int = 2,
    val psVersionComp: Int = 2,
    val sourceFile: File? = null,
    val isDoublePreset: Boolean = false,
    val doublePresetMeta: Milkdrop3DoublePresetMeta? = null
)

data class Milkdrop3DoublePresetMeta(
    val patternName: String = "PLASMA",
    val blendRatio: Float = 0.5f,
    val blendDuration: Float = 6.0f,
    val plasmaSeed: Float = 1.0f,
    val isDirectionLocked: Boolean = false,
    val isFlipped: Boolean = false,
    val autoBeatSwitch: Boolean = true
)

