    var warpAnimSpeed: Float = 1.0f,
    var warpScale: Float = 1.0f,
    var cx: Float = 0.5f,
    var cy: Float = 0.5f,
    var dx: Float = 0.0f,
    var dy: Float = 0.0f,
    var sx: Float = 1.0f,
    var sy: Float = 1.0f,

    var obSize: Float = 0.0f,
    var obR: Float = 0.0f,
    var obG: Float = 0.0f,
    var obB: Float = 0.0f,
    var obA: Float = 0.0f,

    var ibSize: Float = 0.0f,
    var ibR: Float = 0.0f,
    var ibG: Float = 0.0f,
    var ibB: Float = 0.0f,
    var ibA: Float = 0.0f,

    var mvX: Int = 12,
    var mvY: Int = 9,
    var mvDx: Float = 0.0f,
    var mvDy: Float = 0.0f,
    var mvL: Float = 0.9f,
    var mvR: Float = 1.0f,
    var mvG: Float = 1.0f,
    var mvB: Float = 1.0f,
    var mvA: Float = 0.0f,

