data class MilkShaderIR(
    val rawSource: String,
    val glslSource: String,
    val isValid: Boolean,
    val uniforms: List<String> = emptyList(),
    val diagnostics: List<PresetDiagnostic> = emptyList()
)

data class MilkTextureReference(
    val slot: Int,
    val key: String,
    val relativePath: String
)

/**
 * Intermediate compiled representation of an executable AST program.
 */
sealed class CompiledStatement {
    data class Assignment(
        val targetSlot: Int,
        val targetName: String,
        val expr: ExpressionASTNode,
        val op: AssignmentOperator = AssignmentOperator.SET
    ) : CompiledStatement()

    data class GMegabufWrite(
        val indexExpr: ExpressionASTNode,
        val expr: ExpressionASTNode,
        val op: AssignmentOperator = AssignmentOperator.SET
    ) : CompiledStatement()

    data class MegabufWrite(
        val indexExpr: ExpressionASTNode,
        val expr: ExpressionASTNode,
        val op: AssignmentOperator = AssignmentOperator.SET
    ) : CompiledStatement()

    data class LoopStatement(
        val countExpr: ExpressionASTNode,
        val body: List<CompiledStatement>
    ) : CompiledStatement()

    data class UnsupportedStatement(
        val rawText: String,
        val reason: String
    ) : CompiledStatement()
}

typealias CompiledAssignmentNode = CompiledStatement.Assignment

data class MilkdropProgramIR(
    val statements: List<CompiledStatement>,
    val variableNames: List<String>,
    val nameToSlotMap: Map<String, Int>,
    val totalSlots: Int
) {
    // Backwards compatibility property
    val assignments: List<CompiledAssignmentNode>
        get() = statements.filterIsInstance<CompiledAssignmentNode>()
}

enum class AssignmentOperator {
    SET, ADD, SUB, MUL, DIV
}

/**
 * Full MilkPreset Intermediate Representation.
 */
data class MilkPresetIR(
    val metadata: MilkPresetMetadata,
    val staticParams: MilkStaticParameters,
    val presetInitProgram: MilkdropProgramIR? = null,
    val perFrameProgram: MilkdropProgramIR? = null,
    val perVertexProgram: MilkdropProgramIR? = null,
    val customWaves: List<MilkCustomWaveIR> = emptyList(),
    val customShapes: List<MilkCustomShapeIR> = emptyList(),
    val warpShader: MilkShaderIR? = null,
    val compositeShader: MilkShaderIR? = null,
    val textureReferences: List<MilkTextureReference> = emptyList(),
    val diagnostics: List<PresetDiagnostic> = emptyList(),
    val compatibility: PresetCompatibilityReport? = null,
    val secondaryPresetIR: MilkPresetIR? = null
)
